#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# AWS setup for the MPGA board document library.
#
#   Production (new):  mpgagolf-library        private library bucket
#   Test (new):        mpgagolf-test           public media bucket (media/* readable)
#                      mpgagolf-library-test   private library bucket
#   IAM:               mpga-dev user limited to the two test buckets (keys go to dev .env files)
#                      production app user gains read/write on mpgagolf-library
#
# The live bucket (mpgagolf) is only ever read: its policy and contents are never changed.
# Run from anywhere in the repo:  scripts/setup-aws-library.sh

REGION="us-west-2"
LIVE_BUCKET="mpgagolf"
MEDIA_PREFIX="media"
PROD_LIBRARY_BUCKET="mpgagolf-library"
TEST_MEDIA_BUCKET="mpgagolf-test"
TEST_LIBRARY_BUCKET="mpgagolf-library-test"
DEV_USER="mpga-dev"
ADMIN_ENV="apps/admin/.env.docker"
PUBLIC_ENV="apps/public/.env.docker"
# Answers worth remembering between runs that don't belong in app config (git-ignored).
STATE_FILE="scripts/.setup-aws-library.state"

# run CMD...: show a command, then run it. Output stays on screen.
run() {
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  "$@"
}

# bucket_state NAME: prints "mine", "missing" or "taken" (exists in another account).
bucket_state() {
  local out
  if out=$(aws s3api head-bucket --bucket "$1" 2>&1); then echo mine; return; fi
  case "$out" in
    *404*|*"Not Found"*|*NoSuchBucket*) echo missing ;;
    *) echo taken ;;
  esac
}

# create_private_bucket NAME VERSIONING(on|off)
create_private_bucket() {
  local name="$1" versioning="$2" state
  state=$(bucket_state "$name")
  if [[ "$state" == taken ]]; then
    warn "$name exists in another AWS account (bucket names are global). Pick a new name,"
    warn "edit it at the top of this script, and re-run."
    exit 1
  fi
  if [[ "$state" == mine ]]; then
    note "$name already exists in your account, so it won't be created again; its settings are re-applied."
  else
    run aws s3api create-bucket --bucket "$name" --region "$REGION" \
      --create-bucket-configuration "LocationConstraint=$REGION" >/dev/null
  fi
  run aws s3api put-public-access-block --bucket "$name" --public-access-block-configuration \
    BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true
  run aws s3api put-bucket-encryption --bucket "$name" --server-side-encryption-configuration \
    '{"Rules":[{"ApplyServerSideEncryptionByDefault":{"SSEAlgorithm":"AES256"}}]}'
  if [[ "$versioning" == on ]]; then
    run aws s3api put-bucket-versioning --bucket "$name" --versioning-configuration Status=Enabled
  fi
  run aws s3api put-bucket-tagging --bucket "$name" --tagging 'TagSet=[{Key=project,Value=mpga},{Key=purpose,Value=board-library}]'
  printf '  %s✓%s %s is private and ready\n' "$GREEN" "$RESET" "$name"
}

# as_dev CMD...: run a command with the mpga-dev keys instead of the admin profile.
as_dev() {
  # Drop any session token inherited from the shell: sent alongside the dev user's permanent
  # keys it would make every request fail authentication.
  env -u AWS_PROFILE -u AWS_SESSION_TOKEN -u AWS_SECURITY_TOKEN \
    AWS_ACCESS_KEY_ID="$DEV_KEY_ID" AWS_SECRET_ACCESS_KEY="$DEV_SECRET" \
    AWS_DEFAULT_REGION="$REGION" "$@"
}

# same_user A B: IAM user names are case-insensitive.
same_user() {
  [[ "$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')" == "$(printf '%s' "$2" | tr '[:upper:]' '[:lower:]')" ]]
}

# remember KEY VALUE: save a wizard answer to the state file (not an app .env file).
# Same KEY='VALUE' format as write_env (so ask/_existing read it back), but kept out of the
# summary of app settings written.
remember() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$STATE_FILE" ]] || (umask 077 && : > "$STATE_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$STATE_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$STATE_FILE"
  rm -f "$tmp"
}

run_wizard() {

TOTAL_STAGES=12
cd "$(git rev-parse --show-toplevel)"
ENV_FILE="$ADMIN_ENV"
CHECK_FILE=$(mktemp)
printf 'mpga wizard check %s\n' "$(date -u +%FT%TZ)" > "$CHECK_FILE"
trap 'rm -f "$CHECK_FILE"' EXIT

banner "AWS setup: board library buckets and an isolated dev environment"

# ── 1 ────────────────────────────────────────────────────────────────────────
stage "AWS CLI"
if command -v aws >/dev/null 2>&1; then
  say "Found $(aws --version 2>&1)."
else
  say "The AWS CLI isn't installed. It's needed to create the buckets and the dev user."
  if command -v brew >/dev/null 2>&1 && confirm "Install it now with Homebrew (brew install awscli)?"; then
    run brew install awscli
  else
    open_url "https://docs.aws.amazon.com/cli/latest/userguide/getting-started-install.html"
    warn "Install the AWS CLI, then re-run this script."
    exit 1
  fi
fi
pause

# ── 2 ────────────────────────────────────────────────────────────────────────
stage "Sign in with an AWS admin profile"
say "This wizard needs an AWS sign-in that can manage S3 and IAM (an administrator)."
say "The profile name is just a local label in your AWS CLI config (~/.aws), not an IAM user,"
say "and nothing from it is stored in this repo."
note "Don't use the app's own keys from $ADMIN_ENV here."
printf '\n'
ask ADMIN_PROFILE "AWS CLI profile name (Enter for mpga-admin; created if new):"
ADMIN_PROFILE="${ADMIN_PROFILE:-mpga-admin}"
# Credentials in the environment would override the profile; make sure the profile is used.
if [[ -n "${AWS_ACCESS_KEY_ID:-}${AWS_SECRET_ACCESS_KEY:-}${AWS_SESSION_TOKEN:-}" ]]; then
  note "Ignoring AWS credentials set in this shell so profile '$ADMIN_PROFILE' is used."
fi
unset AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY AWS_SESSION_TOKEN AWS_SECURITY_TOKEN
export AWS_PROFILE="$ADMIN_PROFILE" AWS_DEFAULT_REGION="$REGION"
if ! aws sts get-caller-identity >/dev/null 2>&1; then
  say "No working sign-in for profile '$ADMIN_PROFILE' yet."
  say "We'll use ${BOLD}aws login${RESET}: it signs the CLI in with your normal AWS console login and"
  say "issues short-lived credentials (up to 12 hours), so no access keys are created."
  note "Sign in as an administrator. Root works, but an IAM user with admin rights is better"
  note "practice; IAM users also need the SignInLocalDevelopmentAccess policy for aws login."
  CLI_VERSION=$(aws --version 2>&1 | sed -nE 's#^aws-cli/([0-9]+\.[0-9]+)\..*#\1#p')
  CLI_MAJOR=${CLI_VERSION%%.*} CLI_MINOR=${CLI_VERSION#*.}
  if [[ -z "$CLI_VERSION" ]] || (( CLI_MAJOR < 2 || (CLI_MAJOR == 2 && CLI_MINOR < 32) )); then
    warn "aws login needs AWS CLI 2.32 or newer (you have ${CLI_VERSION:-an unknown version})."
    if command -v brew >/dev/null 2>&1 && confirm "Upgrade it now with Homebrew (brew upgrade awscli)?"; then
      run brew upgrade awscli
    else
      open_url "https://docs.aws.amazon.com/cli/latest/userguide/getting-started-install.html"
      warn "Upgrade the AWS CLI, then re-run this script."
      exit 1
    fi
  fi
  step "A browser window opens: sign in to the AWS console and approve the CLI request."
  step "If asked for a default region, enter $REGION."
  run aws login --profile "$ADMIN_PROFILE"
  if ! aws sts get-caller-identity >/dev/null 2>&1; then
    warn "Still no working sign-in for '$ADMIN_PROFILE'. Run: aws login --profile $ADMIN_PROFILE"
    warn "then re-run this script."
    exit 1
  fi
fi
IDENTITY=$(aws sts get-caller-identity --query Arn --output text)
ACCOUNT_ID=$(aws sts get-caller-identity --query Account --output text)
say "Signed in as: ${BOLD}$IDENTITY${RESET}"
say "AWS account:  $ACCOUNT_ID"
confirm "Is this the AWS account that owns the $LIVE_BUCKET bucket?" || { warn "Stopping. Re-run with the right profile."; exit 1; }

# ── 3 ────────────────────────────────────────────────────────────────────────
stage "Look at the current setup (read-only)"
say "Nothing is changed in this stage."
printf '\n'
say "${BOLD}$LIVE_BUCKET${RESET} region:"
run aws s3api get-bucket-location --bucket "$LIVE_BUCKET" --output text || true
say "${BOLD}$LIVE_BUCKET${RESET} public access settings:"
run aws s3api get-public-access-block --bucket "$LIVE_BUCKET" --output json 2>/dev/null || note "(none set on the bucket)"
say "${BOLD}$LIVE_BUCKET${RESET} bucket policy:"
run aws s3api get-bucket-policy --bucket "$LIVE_BUCKET" --query Policy --output text 2>/dev/null || note "(no bucket policy)"
say "Account-wide public access block:"
if run aws s3control get-public-access-block --account-id "$ACCOUNT_ID" --output json 2>/dev/null; then
  warn "If BlockPublicPolicy is true account-wide, stage 6 can't make $TEST_MEDIA_BUCKET public."
else
  note "(no account-wide block: buckets decide for themselves)"
fi
APP_KEY_ID=$(ENV_FILE="$ADMIN_ENV" _existing AWS_ACCESS_KEY_ID || true)
APP_USER=""
if [[ -n "$APP_KEY_ID" ]]; then
  APP_USER=$(aws iam get-access-key-last-used --access-key-id "$APP_KEY_ID" --query UserName --output text 2>/dev/null || true)
  say "The key currently in $ADMIN_ENV (${APP_KEY_ID:0:8}…) belongs to IAM user: ${BOLD}${APP_USER:-unknown}${RESET}"
  if [[ -n "$APP_USER" ]] && same_user "$APP_USER" "$DEV_USER"; then
    note "That's the dev user from an earlier run, so it says nothing about production."
    APP_USER=""
  elif [[ -n "$APP_USER" && "$APP_USER" != "None" ]]; then
    note "Dev has been using this key, which can write to the live bucket. Stage 8 replaces it in dev."
    remember LIVE_KEY_USER "$APP_USER"
  fi
fi
# A production user found on an earlier run (before dev switched keys) is still the best guess.
[[ -z "$APP_USER" ]] && APP_USER=$(ENV_FILE="$STATE_FILE" _existing LIVE_KEY_USER || true)
pause

# ── 4 ────────────────────────────────────────────────────────────────────────
stage "Create $PROD_LIBRARY_BUCKET (production, private)"
say "Where board documents live in production. No public access, encrypted, and versioned so"
say "an accidental overwrite or delete can be recovered."
if confirm "Create/configure $PROD_LIBRARY_BUCKET in $REGION?"; then
  create_private_bucket "$PROD_LIBRARY_BUCKET" on
else
  SKIPPED+=("create $PROD_LIBRARY_BUCKET")
fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────────
stage "Create $TEST_LIBRARY_BUCKET (test, private)"
say "The dev/test stand-in for the library bucket. Same settings, no versioning."
if confirm "Create/configure $TEST_LIBRARY_BUCKET in $REGION?"; then
  create_private_bucket "$TEST_LIBRARY_BUCKET" off
else
  SKIPPED+=("create $TEST_LIBRARY_BUCKET")
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────────
stage "Create $TEST_MEDIA_BUCKET (test, public media)"
say "A copy of the live site's public bucket for dev: anyone can read files under $MEDIA_PREFIX/,"
say "nothing else, and ACLs stay disabled. Dev uploads and published documents land here."
if confirm "Create/configure $TEST_MEDIA_BUCKET with public read on $MEDIA_PREFIX/*?"; then
  case "$(bucket_state "$TEST_MEDIA_BUCKET")" in
    taken) warn "$TEST_MEDIA_BUCKET belongs to another account. Rename it at the top of this script."; exit 1 ;;
    mine) note "$TEST_MEDIA_BUCKET already exists in your account, so it won't be created again." ;;
    *) run aws s3api create-bucket --bucket "$TEST_MEDIA_BUCKET" --region "$REGION" \
         --create-bucket-configuration "LocationConstraint=$REGION" >/dev/null ;;
  esac
  # Policies may grant public read; ACLs may not.
  run aws s3api put-public-access-block --bucket "$TEST_MEDIA_BUCKET" --public-access-block-configuration \
    BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=false,RestrictPublicBuckets=false
  POLICY_FILE=$(mktemp)
  cat > "$POLICY_FILE" <<JSON
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "PublicReadMedia",
    "Effect": "Allow",
    "Principal": "*",
    "Action": "s3:GetObject",
    "Resource": "arn:aws:s3:::$TEST_MEDIA_BUCKET/$MEDIA_PREFIX/*"
  }]
}
JSON
  run aws s3api put-bucket-policy --bucket "$TEST_MEDIA_BUCKET" --policy "file://$POLICY_FILE"
  rm -f "$POLICY_FILE"
  run aws s3api put-bucket-tagging --bucket "$TEST_MEDIA_BUCKET" --tagging 'TagSet=[{Key=project,Value=mpga},{Key=purpose,Value=dev-media}]'
  printf '  %s✓%s %s is ready (public read on %s/*)\n' "$GREEN" "$RESET" "$TEST_MEDIA_BUCKET" "$MEDIA_PREFIX"
else
  SKIPPED+=("create $TEST_MEDIA_BUCKET")
fi
pause

# ── 7 ────────────────────────────────────────────────────────────────────────
stage "Copy live media into $TEST_MEDIA_BUCKET (one time)"
say "So existing documents and photos keep working in dev, and the library migration can be"
say "rehearsed on real files. $LIVE_BUCKET is only read."
say "Measuring $LIVE_BUCKET/$MEDIA_PREFIX/ (this lists every object, so it can take a moment)…"
{ aws s3 ls "s3://$LIVE_BUCKET/$MEDIA_PREFIX/" --recursive --summarize --human-readable | tail -n 2 | sed 's/^/  /'; } \
  || warn "Couldn't measure it (check the admin profile can read $LIVE_BUCKET)."
if confirm "Copy it all to s3://$TEST_MEDIA_BUCKET/$MEDIA_PREFIX/? (re-runs copy only what's new)"; then
  run aws s3 sync "s3://$LIVE_BUCKET/$MEDIA_PREFIX/" "s3://$TEST_MEDIA_BUCKET/$MEDIA_PREFIX/" --only-show-errors
  printf '  %s✓%s copied\n' "$GREEN" "$RESET"
else
  SKIPPED+=("copy $LIVE_BUCKET/$MEDIA_PREFIX to $TEST_MEDIA_BUCKET")
fi
pause

# ── 8 ────────────────────────────────────────────────────────────────────────
stage "Create the $DEV_USER user and point dev at the test buckets"
say "$DEV_USER can read, write, list and delete in $TEST_MEDIA_BUCKET and $TEST_LIBRARY_BUCKET, and"
say "nothing else, so dev can't touch the live site even by mistake."
if confirm "Create/update $DEV_USER and its permissions?"; then
  if aws iam get-user --user-name "$DEV_USER" >/dev/null 2>&1; then
    note "$DEV_USER already exists; updating its policy."
  else
    run aws iam create-user --user-name "$DEV_USER" --tags Key=project,Value=mpga >/dev/null
  fi
  POLICY_FILE=$(mktemp)
  cat > "$POLICY_FILE" <<JSON
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "TestObjects",
      "Effect": "Allow",
      "Action": ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"],
      "Resource": [
        "arn:aws:s3:::$TEST_MEDIA_BUCKET/*",
        "arn:aws:s3:::$TEST_LIBRARY_BUCKET/*"
      ]
    },
    {
      "Sid": "TestBuckets",
      "Effect": "Allow",
      "Action": ["s3:ListBucket"],
      "Resource": [
        "arn:aws:s3:::$TEST_MEDIA_BUCKET",
        "arn:aws:s3:::$TEST_LIBRARY_BUCKET"
      ]
    }
  ]
}
JSON
  run aws iam put-user-policy --user-name "$DEV_USER" --policy-name mpga-test-buckets \
    --policy-document "file://$POLICY_FILE"
  rm -f "$POLICY_FILE"

  CURRENT_DEV_KEY=$(ENV_FILE="$ADMIN_ENV" _existing AWS_ACCESS_KEY_ID || true)
  DEV_KEY_ID="" DEV_SECRET=""
  if [[ -n "$CURRENT_DEV_KEY" ]] && aws iam list-access-keys --user-name "$DEV_USER" \
       --query 'AccessKeyMetadata[].AccessKeyId' --output text | grep -qw "$CURRENT_DEV_KEY"; then
    note "$ADMIN_ENV already holds a $DEV_USER key; keeping it."
    DEV_KEY_ID="$CURRENT_DEV_KEY"
    DEV_SECRET=$(ENV_FILE="$ADMIN_ENV" _existing AWS_SECRET_ACCESS_KEY || true)
  else
    warn "This replaces AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY in $ADMIN_ENV"
    [[ -n "$CURRENT_DEV_KEY" ]] && warn "(currently ${CURRENT_DEV_KEY:0:8}…, owned by ${APP_USER:-unknown})."
    if confirm "Create a new access key for $DEV_USER and write it to $ADMIN_ENV?"; then
      read -r DEV_KEY_ID DEV_SECRET < <(aws iam create-access-key --user-name "$DEV_USER" \
        --query 'AccessKey.[AccessKeyId,SecretAccessKey]' --output text)
      printf '  %s✓%s created key %s…\n' "$GREEN" "$RESET" "${DEV_KEY_ID:0:8}"
    else
      SKIPPED+=("access key for $DEV_USER in $ADMIN_ENV")
    fi
  fi

  ENV_FILE="$ADMIN_ENV"
  if [[ -n "$DEV_KEY_ID" && -n "$DEV_SECRET" ]]; then
    write_env AWS_ACCESS_KEY_ID "$DEV_KEY_ID"
    write_env AWS_SECRET_ACCESS_KEY "$DEV_SECRET"
  fi
  write_env S3_BUCKET_NAME "$TEST_MEDIA_BUCKET"
  write_env S3_MEDIA_PREFIX "$MEDIA_PREFIX"
  # Client components build media links from these (browsers can't read S3_*).
  write_env NEXT_PUBLIC_S3_BUCKET_NAME "$TEST_MEDIA_BUCKET"
  write_env NEXT_PUBLIC_S3_MEDIA_PREFIX "$MEDIA_PREFIX"
  write_env S3_REGION "$REGION"
  write_env S3_LIBRARY_BUCKET "$TEST_LIBRARY_BUCKET"
  write_env S3_LIBRARY_REGION "$REGION"
else
  SKIPPED+=("create $DEV_USER and update $ADMIN_ENV")
fi
pause

# ── 9 ────────────────────────────────────────────────────────────────────────
stage "Point the public dev site at $TEST_MEDIA_BUCKET"
say "The public site builds document and photo links (and allowed image hosts) from"
say "S3_BUCKET_NAME, so dev links must use the test bucket too."
if confirm "Write S3_BUCKET_NAME / NEXT_PUBLIC_S3_BUCKET_NAME=$TEST_MEDIA_BUCKET to $PUBLIC_ENV?"; then
  ENV_FILE="$PUBLIC_ENV"
  write_env S3_BUCKET_NAME "$TEST_MEDIA_BUCKET"
  write_env S3_MEDIA_PREFIX "$MEDIA_PREFIX"
  write_env NEXT_PUBLIC_S3_BUCKET_NAME "$TEST_MEDIA_BUCKET"
  write_env NEXT_PUBLIC_S3_MEDIA_PREFIX "$MEDIA_PREFIX"
  ENV_FILE="$ADMIN_ENV"
else
  SKIPPED+=("S3_BUCKET_NAME in $PUBLIC_ENV")
fi
pause

# ── 10 ───────────────────────────────────────────────────────────────────────
stage "Give the production app access to $PROD_LIBRARY_BUCKET"
say "The production app reads and writes library files and copies published versions into"
say "$LIVE_BUCKET (which it can already write to). This adds only the library bucket."
note "Nothing else about the production user changes. Its keys stay the same."
printf '\n'
[[ -n "$APP_USER" && "$APP_USER" != "None" ]] && say "Best guess from the live key: ${BOLD}$APP_USER${RESET}"
# Defaults to the answer saved on an earlier run (kept in the state file, not app config).
ENV_FILE="$STATE_FILE"
ask PROD_APP_USER "IAM user name the production app runs as (Enter to use ${APP_USER:-none found}):"
ENV_FILE="$ADMIN_ENV"
PROD_APP_USER="${PROD_APP_USER:-$APP_USER}"
if [[ -n "$PROD_APP_USER" ]] && same_user "$PROD_APP_USER" "$DEV_USER"; then
  warn "$DEV_USER is the development user. It must never get production library access."
  PROD_APP_USER=""
fi
if [[ -n "$PROD_APP_USER" ]] && aws iam get-user --user-name "$PROD_APP_USER" >/dev/null 2>&1 \
   && confirm "Add read/write on $PROD_LIBRARY_BUCKET to $PROD_APP_USER?"; then
  remember PROD_APP_USER "$PROD_APP_USER"
  POLICY_FILE=$(mktemp)
  cat > "$POLICY_FILE" <<JSON
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "BoardLibrary",
    "Effect": "Allow",
    "Action": ["s3:GetObject", "s3:PutObject"],
    "Resource": "arn:aws:s3:::$PROD_LIBRARY_BUCKET/*"
  }]
}
JSON
  run aws iam put-user-policy --user-name "$PROD_APP_USER" --policy-name mpga-board-library \
    --policy-document "file://$POLICY_FILE"
  rm -f "$POLICY_FILE"
  printf '  %s✓%s %s can use %s\n' "$GREEN" "$RESET" "$PROD_APP_USER" "$PROD_LIBRARY_BUCKET"
else
  warn "Skipped: no such user, or not confirmed."
  SKIPPED+=("grant $PROD_LIBRARY_BUCKET access to the production app user")
fi
pause

# ── 11 ───────────────────────────────────────────────────────────────────────
stage "Check the dev keys are isolated"
if [[ -z "${DEV_KEY_ID:-}" || -z "${DEV_SECRET:-}" ]]; then
  DEV_KEY_ID=$(ENV_FILE="$ADMIN_ENV" _existing AWS_ACCESS_KEY_ID || true)
  DEV_SECRET=$(ENV_FILE="$ADMIN_ENV" _existing AWS_SECRET_ACCESS_KEY || true)
fi
say "Waiting a few seconds for new IAM keys to take effect…"
for attempt in 1 2 3 4 5 6; do
  as_dev aws s3api head-bucket --bucket "$TEST_LIBRARY_BUCKET" >/dev/null 2>&1 && break
  sleep 5
done
PASS=0 FAIL=0
check() { # check "description" expected(ok|fail) CMD...
  local what="$1" expect="$2"; shift 2
  if "$@" >/dev/null 2>&1; then got=ok; else got=fail; fi
  if [[ "$got" == "$expect" ]]; then PASS=$((PASS + 1)); printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$what"
  else FAIL=$((FAIL + 1)); printf '  %s✗ %s%s\n' "$YELLOW" "$what" "$RESET"; fi
}
check "dev can write to $TEST_LIBRARY_BUCKET" ok \
  as_dev aws s3api put-object --bucket "$TEST_LIBRARY_BUCKET" --key library/wizard-check.txt --body "$CHECK_FILE"
check "dev can read from $TEST_LIBRARY_BUCKET" ok \
  as_dev aws s3api head-object --bucket "$TEST_LIBRARY_BUCKET" --key library/wizard-check.txt
check "dev can write to $TEST_MEDIA_BUCKET" ok \
  as_dev aws s3api put-object --bucket "$TEST_MEDIA_BUCKET" --key "$MEDIA_PREFIX/wizard-check.txt" --body "$CHECK_FILE" --content-type text/plain
check "dev can't list $LIVE_BUCKET" fail \
  as_dev aws s3api list-objects-v2 --bucket "$LIVE_BUCKET" --max-items 1
# Simulated rather than attempted, so nothing is ever written to the live bucket.
SIM=$(aws iam simulate-principal-policy \
  --policy-source-arn "arn:aws:iam::$ACCOUNT_ID:user/$DEV_USER" \
  --action-names s3:PutObject s3:DeleteObject \
  --resource-arns "arn:aws:s3:::$LIVE_BUCKET/$MEDIA_PREFIX/anything" \
  --query 'EvaluationResults[].EvalDecision' --output text 2>/dev/null || echo error)
check "dev can't write to or delete from $LIVE_BUCKET (IAM simulation: $SIM)" ok \
  bash -c '[[ "$1" != *allowed* && "$1" != error ]]' _ "$SIM"
SIM_LIB=$(aws iam simulate-principal-policy \
  --policy-source-arn "arn:aws:iam::$ACCOUNT_ID:user/$DEV_USER" \
  --action-names s3:GetObject s3:PutObject s3:DeleteObject s3:ListBucket \
  --resource-arns "arn:aws:s3:::$PROD_LIBRARY_BUCKET/library/anything" "arn:aws:s3:::$PROD_LIBRARY_BUCKET" \
  --query 'EvaluationResults[].EvalDecision' --output text 2>/dev/null || echo error)
check "dev can't read, write or list $PROD_LIBRARY_BUCKET (IAM simulation: $SIM_LIB)" ok \
  bash -c '[[ "$1" != *allowed* && "$1" != error ]]' _ "$SIM_LIB"
# Use the regional address: brand-new buckets outside us-east-1 answer the global
# <bucket>.s3.amazonaws.com address with a 307 redirect until DNS catches up (hours, up to a day).
regional_url() { printf 'https://%s.s3.%s.amazonaws.com/%s' "$1" "$REGION" "$2"; }
expect_status() { # expect_status "description" CODE URL
  local code; code=$(curl -s -o /dev/null -w '%{http_code}' "$3")
  if [[ "$code" == "$2" ]]; then PASS=$((PASS + 1)); printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"
  else FAIL=$((FAIL + 1)); printf '  %s✗ %s (got HTTP %s)%s\n' "$YELLOW" "$1" "$code" "$RESET"; fi
}
expect_status "public files in $TEST_MEDIA_BUCKET open over HTTPS (200)" 200 \
  "$(regional_url "$TEST_MEDIA_BUCKET" "$MEDIA_PREFIX/wizard-check.txt")"
expect_status "library files in $TEST_LIBRARY_BUCKET are not public (403)" 403 \
  "$(regional_url "$TEST_LIBRARY_BUCKET" library/wizard-check.txt)"
expect_status "library files in $PROD_LIBRARY_BUCKET are not public (403)" 403 \
  "$(regional_url "$PROD_LIBRARY_BUCKET" library/wizard-check.txt)"
GLOBAL_CODE=$(curl -s -o /dev/null -w '%{http_code}' "https://$TEST_MEDIA_BUCKET.s3.amazonaws.com/$MEDIA_PREFIX/wizard-check.txt")
if [[ "$GLOBAL_CODE" == 307 ]]; then
  note "The global address for $TEST_MEDIA_BUCKET still redirects (307): normal for a new bucket."
  note "Browsers follow it, but dev media links may be slow or images may not show until DNS"
  note "catches up (usually a few hours)."
fi
as_dev aws s3api delete-object --bucket "$TEST_LIBRARY_BUCKET" --key library/wizard-check.txt >/dev/null 2>&1 || true
as_dev aws s3api delete-object --bucket "$TEST_MEDIA_BUCKET" --key "$MEDIA_PREFIX/wizard-check.txt" >/dev/null 2>&1 || true
printf '\n'
if (( FAIL )); then
  warn "$FAIL check(s) failed. Fix them before relying on the test setup (re-running is safe)."
  SKIPPED+=("$FAIL isolation check(s) failed in stage 11")
else
  say "${GREEN}All $PASS checks passed.${RESET} Test check files were removed."
fi
pause

# ── 12 ───────────────────────────────────────────────────────────────────────
stage "What's left: restart dev, and production settings for deploy day"
say "${BOLD}Dev${RESET}: restart the containers so they read the new settings:"
note "  docker compose up -d --build admin public"
printf '\n'
say "${BOLD}Production (CapRover, admin app)${RESET}: add these app variables ${BOLD}before${RESET} deploying the"
say "board library branch. Without S3_LIBRARY_BUCKET the library refuses to store files."
note "  S3_LIBRARY_BUCKET=$PROD_LIBRARY_BUCKET"
note "  S3_LIBRARY_REGION=$REGION"
note "  (keep S3_BUCKET_NAME=$LIVE_BUCKET and the existing AWS keys as they are; leave"
note "  NEXT_PUBLIC_S3_BUCKET_NAME unset: it's baked in at build time and defaults to $LIVE_BUCKET)"
printf '\n'
if [[ -n "${CURRENT_DEV_KEY:-}" && "${CURRENT_DEV_KEY:-}" != "${DEV_KEY_ID:-}" ]]; then
  say "${BOLD}Old dev key${RESET}: ${CURRENT_DEV_KEY:0:8}… (user ${APP_USER:-unknown}) is no longer used by dev."
  note "If production uses the same key, leave it. If it was only ever on this laptop, consider"
  note "deactivating it in IAM so a copy of the old .env can't write to the live bucket."
fi
pause "Press Enter for the summary"

finish
}

run_wizard "$@"; exit
